CREATE TABLE document_versions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, document_id BIGINT UNSIGNED NOT NULL, version INT UNSIGNED NOT NULL, storage_key CHAR(64) NOT NULL UNIQUE, original_name VARCHAR(190) NOT NULL, mime VARCHAR(100) NOT NULL, byte_size BIGINT UNSIGNED NOT NULL, checksum CHAR(64) NOT NULL, uploaded_by BIGINT UNSIGNED NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(document_id) REFERENCES documents(id), FOREIGN KEY(uploaded_by) REFERENCES users(id), UNIQUE(document_id,version)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
